/* Yaap brand accent: cobalt blue over the existing Graphite foundation. */
:root{--brand:#2458eb;--brand-hover:#1945c7;--brand-soft:#edf2ff;--brand-mid:#8faafa}
.brand-dot,h1 em{color:var(--brand)}h1 em{font-style:normal}
.hero>.wrap>.eyebrow .dot{background:var(--brand)}
.primary{background:var(--brand);box-shadow:0 2px 3px #1745cd1a}
.primary:hover{background:var(--brand-hover)}
a:focus-visible,summary:focus-visible{outline-color:var(--brand)}
.text-link:hover,.nav a:hover{color:var(--brand)}
.side-active{background:var(--brand-soft);color:#2348a8}
.tabs strong{border-bottom-color:var(--brand)}
.current{stroke:var(--brand);stroke-width:2.25}.area{fill:#2458eb0b}
.metrics>div:first-child{background:var(--brand-soft)}
.feature-number{color:#2453c7}
.bar-one{background:var(--brand)}.bar-two{background:#7898f4}.bar-three{background:#b2c3f9}
.funnel>div{background:#edf2ff;border-left-color:var(--brand)}
.revenue>div:not(.receipt){color:#2453c7}
.architecture{background:#1745cd;border:1px solid #1745cd;color:white}
.architecture-title{color:#ffffffb8}
.worker{background:#ffffff;border-color:#ffffff20;color:#262c32}
.worker strong{color:#2458eb}
.connect-line{border-left-color:#ffffff60}
.infra-grid>div{background:#ffffff0d;border-color:#ffffff38;color:white}
.infra-grid span{color:#e1e9ff}
.architecture p:not(.eyebrow){color:#e1e9ff}
.steps li>span{color:#2453c7}


/* Selected identity: Confluence. Keep outlined lockups proportional. */
.brand-lockup{display:block;width:auto;height:34px;flex-shrink:0}.wordmark>a{display:inline-flex;align-items:center;min-height:44px}.footer .brand-lockup{height:26px}.mini-brand .brand-lockup{height:22px}.worker-brand .brand-lockup{height:30px}.worker-brand{padding:3px 0 2px}@media(max-width:500px){.nav .brand-lockup{height:30px}.footer .brand-lockup{height:24px}}

/* Hero leads directly with the headline; name expansion lives in the footer. */
.hero h1{margin-top:0}

/* Direct section headings and repository placeholder. */
.section-heading h2,.split h2,.setup-top h2,.faq h2{margin-top:0}
.github-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:40px;padding:8px 12px;border:1px solid #262c3226;border-radius:7px;background:#fff;color:#262c32;font:500 13px InterVariable,Arial,sans-serif;white-space:nowrap;cursor:default}.github-button:focus-visible{outline:2px solid var(--brand);outline-offset:4px}.nav{gap:24px}.nav-end{flex:0;white-space:nowrap}@media(max-width:800px){.nav{gap:18px}.github-button{margin-left:auto}.wordmark{flex:1}}@media(max-width:500px){.nav{gap:14px}.github-button{padding:8px 10px}}

/* Compact controls: keep labels readable and reduce the surrounding chrome. */
.button{min-height:36px;padding:8px 12px;gap:10px;border-radius:6px;font-size:14px;line-height:20px}.text-link{gap:8px}.github-button{min-height:32px;padding:6px 10px;gap:6px;border-radius:6px;line-height:18px}.github-button svg{width:16px;height:16px}.primary{box-shadow:none}
